Runs validation checks on the upstream pipeline outputs and writes results to t14_validation_summary.json.
"""

import csv
import json
import os
import sys
from pathlib import Path

# Configuration
OUTPUT_DIR = Path("outputs")
SRC_DIR = Path("src")

# Files to validate
FILES_TO_VALIDATE = [
    "outputs/t01_selected_indicators.csv",
    "outputs/t05_clean_stops.csv",
    "outputs/t08_pois_clean.csv",
    "outputs/t10_accessibility_scores.csv",
    "outputs/t13_city_clusters.csv",
]

def check_file_exists(filepath):
    """Check if a file exists."""
    path = OUTPUT_DIR / filepath
    if not path.exists():
        return False, f"File {filepath} does not exist"
    return True, f"File {filepath} exists"

def check_file_not_empty(filepath):
    """Check if a file is not empty."""
    path = OUTPUT_DIR / filepath
    if not path.exists():
        return False, f"File {filepath} does not exist"
    if path.stat().st_size == 0:
        return False, f"File {filepath} is empty"
    return True, f"File {filepath} has {path.stat().st_size} bytes"

def check_has_header(filepath):
    """Check if a CSV file has a header row."""
    path = OUTPUT_DIR / filepath
    if not path.exists():
        return False, f"File {filepath} does not exist"
    try:
        with open(path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                return False, f"File {filepath} has no header"
            return True, f"File {filepath} has header: {header[0]}"
    except Exception as e:
        return False, f"Error reading header of {filepath}: {e}"

def check_required_columns(filepath, required_cols):
    """Check if a CSV file has all required columns."""
    path = OUTPUT_DIR / filepath
    if not path.exists():
        return False, f"File {filepath} does not exist"
    try:
        with open(path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                return False, f"File {filepath} has no header"
            missing = [col for col in required_cols if col not in header]
            if missing:
                return False, f"File {filepath} missing columns: {', '.join(missing)}"
            return True, f"File {filepath} has all required columns"
    except Exception as e:
        return False, f"Error reading {filepath}: {e}"

def check_row_count(filepath, min_rows):
    """Check if a CSV file has at least min_rows data rows."""
    path = OUTPUT_DIR / filepath
    if not path.exists():
        return False, f"File {filepath} does not exist"
    try:
        with open(path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                return False, f"File {filepath} has no header"
            rows = list(reader)
            if len(rows) < min_rows:
                return False, f"File {filepath} has only {len(rows)} rows, expected at least {min_rows}"
            return True, f"File {filepath} has {len(rows)} data rows"
    except Exception as e:
        return False, f"Error reading {filepath}: {e}"

def check_latitude_range(filepath):
    """Check if latitude values are in valid range [-90, 90]."""
    path = OUTPUT_DIR / filepath
    if not path.exists():
        return False, f"File {filepath} does not exist"
    try:
        with open(path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                return False, f"File {filepath} has no header"
            for row_idx, row in enumerate(reader):
                if len(row) < 4:
                    continue
                try:
                    lat = float(row[3])
                    if lat < -90 or lat > 90:
                        return False, f"File {filepath} row {row_idx}: latitude {lat} out of range [-90, 90]"
                except ValueError:
                    return False, f"File {filepath} row {row_idx}: invalid latitude value"
        return True, f"File {filepath} all latitude values in valid range"
    except Exception as e:
        return False, f"Error validating {filepath}: {e}"

def check_longitude_range(filepath):
    """Check if longitude values are in valid range [-180, 180]."""
    path = OUTPUT_DIR / filepath
    if not path.exists():
        return False, f"File {filepath} does not exist"
    try:
        with open(path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                return False, f"File {filepath} has no header"
            for row_idx, row in enumerate(reader):
                if len(row) < 4:
                    continue
                try:
                    lon = float(row[3])
                    if lon < -180 or lon > 180:
                        return False, f"File {filepath} row {row_idx}: longitude {lon} out of range [-180, 180]"
                except ValueError:
                    return False, f"File {filepath} row {row_idx}: invalid longitude value"
        return True, f"File {filepath} all longitude values in valid range"
    except Exception as e:
        return False, f"Error validating {filepath}: {e}"

def check_required_field_not_empty(filepath, field_name):
    """Check if a required field is not empty in any row."""
    path = OUTPUT_DIR / filepath
    if not path.exists():
        return False, f"File {filepath} does not exist"
    try:
        with open(path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                return False, f"File {filepath} has no header"
            if field_name not in header:
                return False, f"File {filepath} does not have column {field_name}"
            for row_idx, row in enumerate(reader):
                if len(row) <= header.index(field_name):
                    continue
                if not row[header.index(field_name)]:
                    return False, f"File {filepath} row {row_idx}: field '{field_name}' is empty"
        return True, f"File {filepath} all '{field_name}' fields are non-empty"
    except Exception as e:
        return False, f"Error validating {filepath}: {e}"

def main():
    validation_results = []

    # Define checks for each file
    file_checks = {
        "outputs/t01_selected_indicators.csv": [
            ("File exists", check_file_exists),
            ("File not empty", check_file_not_empty),
            ("Has header", check_has_header),
            ("Has required columns", check_required_columns, ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"]),
            ("Has data rows", check_row_count, 1),
        ],
        "outputs/t05_clean_stops.csv": [
            ("File exists", check_file_exists),
            ("File not empty", check_file_not_empty),
            ("Has header", check_has_header),
            ("Has required columns", check_required_columns, ["stop_id", "stop_name", "stop_lat", "stop_lon"]),
            ("Has data rows", check_row_count, 1),
            ("Latitude range", check_latitude_range),
            ("Longitude range", check_longitude_range),
        ],
        "outputs/t08_pois_clean.csv": [
            ("File exists", check_file_exists),
            ("File not empty", check_file_not_empty),
            ("Has header", check_has_header),
            ("Has required columns", check_required_columns, ["qid", "label", "poi_type", "latitude", "longitude", "source"]),
            ("Has data rows", check_row_count, 1),
            ("Latitude range", check_latitude_range),
            ("Longitude range", check_longitude_range),
        ],
        "outputs/t10_accessibility_scores.csv": [
            ("File exists", check_file_exists),
            ("File not empty", check_file_not_empty),
            ("Has header", check_has_header),
            ("Has required columns", check_required_columns, ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"]),
            ("Has data rows", check_row_count, 1),
            ("accessibility_score not empty", check_required_field_not_empty, "accessibility_score"),
        ],
        "outputs/t13_city_clusters.csv": [
            ("File exists", check_file_exists),
            ("File not empty", check_file_not_empty),
            ("Has header", check_has_header),
            ("Has required columns", check_required_columns, ["city_id", "city_name", "year", "cluster_id"]),
            ("Has data rows", check_row_count, 1),
        ],
    }

    # Run validation for each file
    for filepath in FILES_TO_VALIDATE:
        if filepath in file_checks:
            for check_name, check_func, *args in file_checks[filepath]:
                if args:
                    passed, message = check_func(filepath, *args)
                else:
                    passed, message = check_func(filepath)
                validation_results.append({
                    "check_name": check_name,
                    "passed": passed,
                    "message": message
                })
        else:
            if (OUTPUT_DIR / filepath).exists():
                validation_results.append({
                    "check_name": f"File {filepath} exists",
                    "passed": True,
                    "message": f"File {filepath} exists"
                })
            else:
                validation_results.append({
                    "check_name": f"File {filepath} exists",
                    "passed": False,
                    "message": f"File {filepath} does not exist"
                })

    # Write results to JSON file
    output_path = OUTPUT_DIR / "t14_validation_summary.json"
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(validation_results, f, indent=2)

    # Print summary
    passed_count = sum(1 for r in validation_results if r["passed"])
    total_count = len(validation_results)
    print(f"Validation complete: {passed_count}/{total_count} checks passed")
    print(f"Results written to {output_path}")

    return 0

if __name__ == "__main__":
    sys.exit(main())

